def translate(r,pos,fingers=.04,duration=2.,label='translate'):
    obs=r.get_obs(cameras=[],video='none');now=np.array(obs.meta['proprio']['now'])
    q=np.clip(now[:7],LIMITS[:,0]+1e-5,LIMITS[:,1]-1e-5)
    start=fk(q)[:3,3];target=np.array(pos)
    rows=[]
    for a in np.linspace(0,1,int(round(duration/.1))):
        q=ik(start+(target-start)*a,FRONT,q)
        rows.append(np.r_[q,fingers,fingers])
    rows.extend([rows[-1]]*10)
