def grip(r,width=0.,label='grip'):
    obs=r.get_obs(cameras=[],video='none');p=np.array(obs.meta['proprio']['now'])
    q=p[23:30];old=p[30:32]
    rows=[np.r_[q,old+(width-old)*a] for a in np.linspace(0,1,12)]
    rows.extend([np.r_[q,width,width]]*15)
    return execute(r,rows,label)
